import{z as E,x as d,o as t,c as m,q as n,j as s,D as e,d as i,s as p,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"最大熵原理","description":"","frontmatter":{"title":"最大熵原理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/max-entropy-principle.md","filePath":"cs/max-entropy-principle.md","lastUpdated":1791413859000}'),_={name:"cs/max-entropy-principle.md"};function h(A,a,D,c,B,f){const o=d("Mermaid");return t(),m("div",null,[a[2]||(a[2]=n('<h1 id="最大熵原理" tabindex="-1">最大熵原理 <a class="header-anchor" href="#最大熵原理" aria-label="Permalink to &quot;最大熵原理&quot;">​</a></h1><div class="epigraph"><p>只知道若干期望约束时，选使 $H$ 最大的 $p$——等价于相对均匀分布的 KL 最小；指数族由此出现。</p><footer>—— 据 Jaynes, Information Theory and Statistical Mechanics, 1957；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/kl-cross-entropy">KL 与交叉熵</a> 给出 \\(D(p\\|q)\\)。缺口是<strong>选分布</strong>：约束 \\(\\mathbb{E}_p[f_i]=a_i\\)，其余未知。Jaynes：最大化 \\(H(p)\\)，或 \\(\\min D(p\\|u)\\)（\\(u\\) 均匀）。拉格朗日得 \\(p(x)\\propto\\exp(\\sum\\lambda_i f_i(x))\\)。信息单元以此收束，下一单元数论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>约束不足时，分布不唯一。再人为加峰会引入没有证据的信息（KL 意义下相对均匀更远）。最大熵选最平的那个。有均值约束的非负半轴上得指数分布；有均值方差得高斯——在给定支撑与测度下。离散字母表上，无约束即均匀，熵最大 \\(\\log|\\mathcal{X}|\\)，与<a href="/cs/entropy-bits">熵课</a> 一致。</p><p><span class="marginnote">直觉类比：最大熵是最「不脑补」的猜法——只知道平均身高 170，就别再编「人群偏好对称偏右」之类没有证据的结构。在所有满足已知约束的分布里挑最平的那个，任何多余的峰谷都是自己夹带的私货。</span></p><p>不是「自然界最大化熵」的物理学断言；本课当推理规则。统计力学是 Jaynes 的动机，不是本栏主线。</p><h3 id="不是最大似然的别名" tabindex="-1">不是最大似然的别名 <a class="header-anchor" href="#不是最大似然的别名" aria-label="Permalink to &quot;不是最大似然的别名&quot;">​</a></h3><p>有了完整 i.i.d. 样本，MLE 另说。最大熵用于<strong>矩约束</strong>而非整份经验分布。经验分布本身已是一种最大熵（无额外约束时在类型上）。</p><p><span class="marginnote">Jaynes 1957。Cover–Thomas 第 12 章。Csiszár 的 \\(I\\)-投影：约束凸集上最小 KL。本课不把 CRF 特征当主例子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写拉格朗日：\\(H+\\sum\\lambda_i(\\mathbb{E}f_i-a_i)\\)。指出解在指数族。对偶：\\(\\lambda\\) 使约束满足。强调：换参考测度 \\(q_0\\) 则 \\(\\min D(p\\|q_0)\\)，指数里多一个 \\(\\log q_0\\)。</p><p><span class="marginnote">术语翻译：指数族 \\(p(x)\\propto\\exp(\\sum\\lambda_i f_i(x))\\) 的直白读法——把每条约束的特征量 \\(f_i\\) 加权求和、取指数、再归一化。约束的目标值 \\(a_i\\) 变了，只是乘子 \\(\\lambda_i\\) 跟着调，骨架不变；「矩约束的最大熵分布总长着指数族的形状」说的就是这件事。</span></p>',13)),(t(),s(l,null,{default:e(()=>[p(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E7%9F%A9%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20MAXH%5B%22max%20H(p)%22%5D%0A%20%20MAXH%20--%3E%20EXP%5B%22%E6%8C%87%E6%95%B0%E6%97%8F%20p%20%E2%88%9D%20e%5E%7B%CE%BB%C2%B7f%7D%22%5D%0A%20%20EXP%20--%3E%20KLMIN%5B%22%3D%20min%20D(p%7C%7C%E5%9D%87%E5%8C%80)%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"信息与编码课序结束：信源、信道、有损、相对熵、选分布。后文密码数论不再用 \\(R(D)\\)，除非点名。最大熵给「缺省分布」一个信息论名字，避免在逻辑单元用概率时偷偷换先验而不声明。",-1)),a[5]||(a[5]=r("p",null,"同一条规则，约束从零条到两条，缺省分布换了三次：",-1)),(t(),s(l,null,{default:e(()=>[p(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22%E6%97%A0%E7%9F%A9%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20U%5B%22%E5%9D%87%E5%8C%80%E5%88%86%E5%B8%83%22%5D%0A%20%20R1%5B%22%E5%8F%AA%E7%BA%A6%E6%9D%9F%E5%9D%87%E5%80%BC%22%5D%20--%3E%20E%5B%22%E6%8C%87%E6%95%B0%E5%88%86%E5%B8%83%22%5D%0A%20%20R2%5B%22%E7%BA%A6%E6%9D%9F%E5%9D%87%E5%80%BC%E4%B8%8E%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20G%5B%22%E9%AB%98%E6%96%AF%E5%88%86%E5%B8%83%22%5D%0A%20%20U%20--%3E%20RULE%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E8%A7%84%E5%88%99%EF%BC%9A%E7%BA%A6%E6%9D%9F%E5%86%85%20max%20H%22%5D%0A%20%20E%20--%3E%20RULE%0A%20%20G%20--%3E%20RULE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>与 Kolmogorov：最大熵是分布层；\\(K\\) 是单串。</p><p>\\(I\\)-投影：在凸约束集上 \\(\\min D(p\\|q_0)\\) 唯一（严格凸）。最大熵是 \\(q_0\\) 均匀的特例。经验矩当约束时，解随样本变，这是统计，不是再定义 \\(H\\)。信息单元到此：五把尺子 \\(H,C,R(D),D,\\max H\\) 都有了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证大偏差的 Sanov 全文，不引入热力学极限。不把机器学习的正则当 Jaynes。后课默认：只有矩时，缺省 \\(p\\) 是最大熵指数族。下一课模运算，为密码准备。</p><p>约束不足时最大熵给缺省分布，不是声称物理系统在最大化 \\(H\\)。指数族由拉格朗日出现。下一单元改做模算术，不再用 \\(R(D)\\)。</p><p><span class="marginnote">常见误区：初学者容易把最大熵读成「自然界在最大化熵」的物理定律。它首先是选分布的推理规则：证据只有矩时，最大熵是不夹带私货的缺省；一旦约束改变，「最大熵分布」也跟着换——规则恒定，答案随证据走。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>矩约束下选 \\(\\max H\\) 的 \\(p\\)，得指数族。</li><li>等价于相对均匀（或参考测度）的最小 KL。</li><li>是推理规则，不是物理定律课。</li><li>出处：Jaynes, 1957；Cover and Thomas。</li></ul>',8))])}const x=E(_,[["render",h]]);export{b as __pageData,x as default};
